from scapy.all import rdpcap, Raw, IP, TCP, DNS, UDP

pcap = rdpcap("/home/kou/Desktop/repo/mcparrot/tests/forensics_data_siege/capture.pcap")

# Check for DNS, UDP, or other protocols
for i, pkt in enumerate(pcap):
    if pkt.haslayer(DNS):
        print(f"Packet {i}: DNS - {pkt.summary()}")
    if pkt.haslayer(UDP) and not pkt.haslayer(DNS):
        print(f"Packet {i}: UDP - {pkt.summary()}")

# Let me also extract all raw data streams by conversation
print("\n=== TCP Conversations ===")
from collections import defaultdict
conversations = defaultdict(list)
for i, pkt in enumerate(pcap):
    if pkt.haslayer(TCP) and pkt.haslayer(IP) and pkt.haslayer(Raw):
        key = (pkt[IP].src, pkt[TCP].sport, pkt[IP].dst, pkt[TCP].dport)
        conversations[key].append((i, pkt[Raw].load))

for (src, sport, dst, dport), pkts in conversations.items():
    print(f"\n--- {src}:{sport} -> {dst}:{dport} ({len(pkts)} packets) ---")
    for idx, data in pkts[:5]:  # first 5
        try:
            text = data.decode('utf-8', errors='replace')
            if len(text) < 500:
                print(f"  Packet {idx}: {text[:200]}")
            else:
                print(f"  Packet {idx}: {text[:200]}...")
        except:
            print(f"  Packet {idx}: {repr(data[:100])}")

